ortBannerTitle:"Address copied",supportBannerBody:"Telegram will open in a moment. Then: Send → Paste. The address is already on your clipboard — no need to copy again in TiLi.",supportOpenTelegramOnly:"Open Telegram only",supportCopyAgain:"Copy address again",supportSendTelegram:"Copy and open Telegram",supportSendCopyOnly:"Address copied. On your phone: Telegram → Wallet → Send → paste the address. Coin: USDT, TON network.",supportSendCopyOnlyFail:"Telegram → Wallet → Send → paste the address below. USDT, TON network.",supportSendTon:"Address copied. Your wallet should open — choose USDT (TON) and the amount.",supportSendTonNoCopy:"Opening your wallet. If the address is empty, tap “Copy address”.",supportSendWeb:"Address copied. Telegram will open — Wallet → Send → paste the address, USDT (TON).",supportSendWebNoCopy:"Opening Telegram. Copy the address below and paste it into the transfer.",supportOpenTelegram:"Open Telegram Wallet",supportAddressPending:"The wallet address will appear here soon.",authCta:"Create account / Sign in",profile:"Profile",guest:"Guest",accountOnPhone:"Account on this phone",guestHint:"One profile for calendar and wishes. Works without sign-up; data stays on this phone. You can create an account any time.",accountHint:"No cloud yet: name, email and password live on this device. One account for calendar and wishes.",name:"Name",email:"Email",nameTooShort:"Name needs at least 2 characters",nameSaved:"Name saved",badEmail:"Enter a valid email",accountNotFound:"No account found on this phone",profileSaved:"Profile saved",emailTaken:"This email is already used on this phone",saveFailed:"Could not save",logoutTitle:"Sign out?",logoutMsg:"Tasks will stay. You can sign in again with the same email on this phone.",logout:"Sign out",deleteAccountTitle:"Delete account?",deleteAccount:"Delete account",password:"Password",loginFirst:"Sign in first",passwordMin:"New password must be at least 6 characters",passwordMismatch:"Passwords do not match",pass